package com.example.demo.endpoint; import org.springframework.ws.server.endpoint.annotation.*; import org.springframework.stereotype.Component; import org.w3c.dom.Element; @Endpoint @Component public class UserEndpoint { @PayloadRoot(namespace="http://example.com/demo/webservice",localPart="GetUserRequest") @ResponsePayload public Element getUser(@RequestPayload Element request){return request.getOwnerDocument().createElementNS("http://example.com/demo/webservice","GetUserResponse");} }